import 'package:flutter/material.dart'; import '../../../core/network/football_repository.dart';
class FanLeagueScreen extends StatelessWidget{const FanLeagueScreen({super.key});@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('Fan League')),body:FutureBuilder<List<dynamic>>(future:FootballRepository().leaderboard(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView.builder(padding:const EdgeInsets.all(16),itemCount:s.data!.length,itemBuilder:(_,i){final x=s.data![i];return Card(child:ListTile(leading:CircleAvatar(child:Text('${i+1}')),title:Text(x['user']?['name']??'Fan'),subtitle:Text('@${x['user']?['username']??''}'),trailing:Text('${x['total_points']} pts',style:Theme.of(context).textTheme.titleMedium)));});}));}}
